import { IContract } from '../models/Contract.model';
import { SimulationRequest, SimulationResult } from '../models/Simulation.types';

/**
 * Explicit development and test adapter for simulation.
 * All outputs generated by this adapter are explicitly tagged with `isMock: true`
 * and labeled as synthetic development fixtures.
 */
export const simulationMockAdapter = {
  isMockAdapter: true,

  generateMockResult(request: SimulationRequest, contract?: IContract): SimulationResult {
    const cid = contract?.id || request.contractId;
    const title = contract?.title || `Mock Contract (${cid})`;
    const counterparty = contract?.counterparty || 'Mock Counterparty Inc.';
    const baselineExposure = contract?.financialExposureINR || 500000;

    let directCost = 250000;
    let downstreamCost = 750000;
    let scenarioDesc = 'Synthetic vendor default event simulated under mock adapter';

    if (request.scenarioType === 'early_termination') {
      directCost = 150000;
      downstreamCost = 300000;
      scenarioDesc = 'Synthetic early termination calculation under mock adapter';
    } else if (request.scenarioType === 'milestone_failure') {
      directCost = 100000;
      downstreamCost = 200000;
      scenarioDesc = 'Synthetic milestone failure projection under mock adapter';
    }

    const totalExposure = directCost + downstreamCost;

    return {
      simulationId: `sim-mock-${Date.now()}`,
      status: 'success',
      timestamp: new Date().toISOString(),
      isMock: true,
      scenarioType: request.scenarioType,
      simulationDate: request.simulationDate,
      baseline: {
        contractId: cid,
        contractTitle: title,
        counterparty,
        baselineExposureINR: baselineExposure,
        baselineMilestonesCount: 4,
        baselineOverdueCount: 0,
        riskLevel: contract?.riskLevel || 'medium',
      },
      simulated: {
        eventDate: request.params?.defaultDate || request.params?.effectiveDate || request.simulationDate,
        directFinancialImpactINR: directCost,
        downstreamFinancialImpactINR: downstreamCost,
        totalExposureINR: totalExposure,
        deltaExposureINR: totalExposure - baselineExposure,
        costBreakdown: [
          {
            id: 'mock-cost-1',
            category: 'direct_penalty',
            amountINR: directCost,
            description: `${scenarioDesc} (Direct simulated cost)`,
            clauseCitation: 'MOCK-FIXTURE-SEC-4.2',
            isEstimated: true,
            source: 'user_assumption',
            contractId: cid,
          },
          {
            id: 'mock-cost-2',
            category: 'downstream_sla_breach',
            amountINR: downstreamCost,
            description: 'Synthetic downstream SLA cascading liability fixture',
            clauseCitation: 'MOCK-FIXTURE-SEC-9.1',
            isEstimated: true,
            source: 'user_assumption',
            contractId: 'cnt-MOCK-DOWNSTREAM',
          },
        ],
        cascadingEffects: [
          {
            affectedContractId: 'cnt-MOCK-DOWNSTREAM',
            affectedContractTitle: 'Mock Downstream Customer Agreement',
            counterparty: 'Synthetic Retailer Corp',
            relationshipType: 'downstream',
            impactDescription: 'Simulated infrastructure interruption triggering downstream SLA penalty',
            exposureINR: downstreamCost,
            severity: 'high',
            clauseCitation: 'MOCK-SLA-SEC-2.1',
            isDirectBreach: false,
          },
        ],
        simulatedTimelineEvents: [
          {
            id: 'mock-evt-1',
            contractId: cid,
            contractName: title,
            counterparty,
            title: `[MOCK] Hypothetical ${request.scenarioType.replace('_', ' ')} trigger`,
            date: request.params?.defaultDate || request.simulationDate,
            type: 'penalty_trigger',
            severity: 'critical',
            status: 'overdue',
            penaltyAmountINR: directCost,
            description: 'Mock development fixture event trigger',
            clauseCitation: 'MOCK-SEC-1',
            isSimulatedTrigger: true,
          },
        ],
      },
      comparison: {
        exposureDeltaINR: totalExposure - baselineExposure,
        riskLevelBefore: contract?.riskLevel || 'medium',
        riskLevelAfter: 'critical',
        criticalBreachesCount: 2,
        totalAffectedContractsCount: 2,
      },
      dataQuality: {
        hasSufficientData: true,
        confidenceScore: 0.5,
        missingFields: [],
        unverifiedTerms: ['Calculated entirely using synthetic test fixtures'],
        assumptions: [
          'THIS IS SYNTHETIC MOCK DATA — NOT A VERIFIED LEGAL OR FINANCIAL OUTCOME',
          'Mock adapter active for development and isolated unit testing',
        ],
        warnings: ['Mock mode enabled: figures reflect synthetic test fixtures, not verified contractual analysis'],
      },
    };
  },
};
